def calc(expr: str) -> int:
    # Tokenize: integers, operators, parentheses; spaces are skipped.
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c == ' ':
            i += 1
        elif '0' <= c <= '9':
            j = i
            while j < n and '0' <= expr[j] <= '9':
                j += 1
            tokens.append(int(expr[i:j]))
            i = j
        elif c in '+-*/()':
            tokens.append(c)
            i += 1
        else:
            raise ValueError("syntax error")

    prec = {'+': 1, '-': 1, '*': 2, '/': 2}
    out = []   # RPN items: ('n', v), ('u',), ('b', op)
    ops = []   # operator stack: '(', 'u' (unary minus), or binary operator
    expect = True  # True when an operand is expected

    def emit(top):
        if top == 'u':
            out.append(('u',))
        else:
            out.append(('b', top))

    for tok in tokens:
        if expect:
            if isinstance(tok, int):
                out.append(('n', tok))
                expect = False
            elif tok == '-':
                ops.append('u')
            elif tok == '(':
                ops.append('(')
            else:
                raise ValueError("syntax error")
        else:
            if isinstance(tok, int) or tok == '(':
                raise ValueError("syntax error")
            if tok == ')':
                while ops and ops[-1] != '(':
                    emit(ops.pop())
                if not ops:
                    raise ValueError("syntax error")
                ops.pop()
            else:
                p = prec[tok]
                while ops and ops[-1] != '(' and (ops[-1] == 'u' or prec[ops[-1]] >= p):
                    emit(ops.pop())
                ops.append(tok)
                expect = True

    # The expression must end with a complete operand.
    if expect:
        raise ValueError("syntax error")
    while ops:
        top = ops.pop()
        if top == '(':
            raise ValueError("syntax error")
        emit(top)

    # Syntax is fully checked; now evaluate the RPN form.
    st = []
    for item in out:
        if item[0] == 'n':
            st.append(item[1])
        elif item[0] == 'u':
            st.append(-st.pop())
        else:
            op = item[1]
            b = st.pop()
            a = st.pop()
            if op == '+':
                st.append(a + b)
            elif op == '-':
                st.append(a - b)
            elif op == '*':
                st.append(a * b)
            else:
                if b == 0:
                    raise ValueError("division by zero")
                q = abs(a) // abs(b)
                st.append(q if (a < 0) == (b < 0) else -q)
    return st[-1]
